package com.gameaggregator.incidentservice.api;import com.gameaggregator.platform.core.common.web.ApiResponse;import com.gameaggregator.incidentservice.application.IncidentService;import com.gameaggregator.incidentservice.domain.*;import jakarta.validation.Valid;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/incidents") public class IncidentController{final IncidentService s;public IncidentController(IncidentService s){this.s=s;}@PostMapping ApiResponse<Incident> create(@Valid @RequestBody IncidentDtos.Create r){return ApiResponse.success(s.create(r));}@GetMapping ApiResponse<List<Incident>> list(){return ApiResponse.success(s.list());}@GetMapping("/{id}")ApiResponse<Incident> get(@PathVariable UUID id){return ApiResponse.success(s.get(id));}@PostMapping("/{id}/acknowledge")ApiResponse<Incident> acknowledge(@PathVariable UUID id,@Valid @RequestBody IncidentDtos.Actor r){return ApiResponse.success(s.acknowledge(id,r));}@PostMapping("/{id}/assign")ApiResponse<Incident> assign(@PathVariable UUID id,@Valid @RequestBody IncidentDtos.Assign r){return ApiResponse.success(s.assign(id,r));}@PostMapping("/{id}/resolve")ApiResponse<Incident> resolve(@PathVariable UUID id,@Valid @RequestBody IncidentDtos.Actor r){return ApiResponse.success(s.resolve(id,r));}@PostMapping("/{id}/postmortem")ApiResponse<Incident> postmortem(@PathVariable UUID id,@Valid @RequestBody IncidentDtos.Postmortem r){return ApiResponse.success(s.postmortem(id,r));}@PostMapping("/{id}/timeline")ApiResponse<IncidentTimeline> timeline(@PathVariable UUID id,@Valid @RequestBody IncidentDtos.Timeline r){return ApiResponse.success(s.add(id,r));}@GetMapping("/{id}/timeline")ApiResponse<List<IncidentTimeline>> timeline(@PathVariable UUID id){return ApiResponse.success(s.timeline(id));}}